变动原因说明：
营业收入变动原因说明：主要系随着“双碳”引领新型电力系统建设升级，物联网与各行业的深
度融合和规模应用，同时公司积极推进海外产能布局和市场拓展带来业绩增长所致。
营业成本变动原因说明：主要系销售增长和结构变化所致。
销售费用变动原因说明：主要系销售增长带来相关市场投入增加。
管理费用变动原因说明：主要系本期股份支付费用分摊较上期减少所致。
财务费用变动原因说明：主要系公司固定利率存款理财未到期结息减少以及汇率波动影响汇兑损
失较上期增加所致。
研发费用变动原因说明：主要系本期股份支付费用分摊较上期减少，同时公司持续加大自主研发
投入和优化研发人员配置带来研发咨询服务费较同期减少所致。
经营活动产生的现金流量净额变动原因说明：主要系本期收到的销售回款增加所致。
投资活动产生的现金流量净额变动原因说明：主要系本期购买固定资产等长期资产支出增加所致。
筹资活动产生的现金流量净额变动原因说明：主要系本报告期股票回购、现金分红增加，以及上
年同期收到员工持股计划认购款所致。
本期公司业务类型、利润构成或利润来源发生重大变动的详细说明
